(function () {
  const { R, C, S, B } = SF, U = SF.u;
  SF.category('Controls', 'Buttons, toggles, sliders, inputs, scrollbars, checkboxes, tooltips and progress bars');
  const rt = (id, name, p, learn, rules, html, bg) => SF.tool({ id, name, cat: 'Controls', p, learn, kind: 'css', zoom: 1.7, r(q) { const code = rules(q); return { css: code, code, html: `<style>${code}</style>${html(q)}`, bg: bg || '#0f1320' }; } });

  rt('c-button', 'Button', [S('style', 'Style', ['Solid', 'Gradient', 'Outline', 'Ghost', 'Soft', '3D press'], 'Gradient'), C('c1', 'Colour', '#7c5cff'), C('c2', 'Second colour', '#ff5c9d'), C('text', 'Text colour', '#ffffff'), R('rad', 'Roundness', 0, 40, 12, 'px'), R('py', 'Height padding', 6, 24, 12, 'px'), R('px', 'Side padding', 10, 48, 26, 'px'), R('fs', 'Text size', 12, 24, 16, 'px'), R('lift', 'Hover lift', 0, 8, 2, 'px', 1, 1)],
    'A button needs a clear resting state and a hover state. Subtle lift and brightness changes feel tactile.',
    p => { const s = p.style; const bg = s === 'Solid' ? `background: ${p.c1}; color: ${p.text};` : s === 'Gradient' ? `background: linear-gradient(135deg, ${p.c1}, ${p.c2}); color: ${p.text};` : s === 'Outline' ? `background: transparent; color: ${p.c1}; border: 2px solid ${p.c1};` : s === 'Ghost' ? `background: transparent; color: ${p.c1};` : s === 'Soft' ? `background: ${U.rgba(p.c1, .15)}; color: ${p.c1};` : `background: ${p.c1}; color: ${p.text}; box-shadow: 0 5px 0 ${U.mix(p.c1, '#000000', .35)};`; return `.sf-button {\n  ${bg}\n  border: ${s === 'Outline' ? '2px solid ' + p.c1 : '0'};\n  border-radius: ${p.rad}px;\n  padding: ${p.py}px ${p.px}px;\n  font: 600 ${p.fs}px system-ui;\n  cursor: pointer;\n  transition: transform .15s, box-shadow .15s, filter .15s;\n}\n.sf-button:hover { transform: translateY(-${p.lift}px); filter: brightness(1.08); }\n.sf-button:active { transform: translateY(${s === '3D press' ? 4 : 1}px)${s === '3D press' ? '; box-shadow: 0 1px 0 ' + U.mix(p.c1, '#000000', .35) : ''}; }`; },
    () => '<button class="sf-button">Click me</button>');

  rt('c-toggle', 'Toggle switch', [R('w', 'Width', 36, 90, 58, 'px'), C('on', 'On colour', '#35d0ba'), C('off', 'Off colour', '#4a5272'), C('knob', 'Knob colour', '#ffffff'), R('gap', 'Knob margin', 1, 8, 3, 'px', 1, 1), B('anim', 'Demo: flip automatically', 1)],
    'A toggle is a checkbox in disguise: the input is hidden, and its :checked state moves a knob with a transition.',
    p => { const h = Math.round(p.w * .55), k = h - p.gap * 2; return `.sf-toggle { position: relative; display: inline-block; width: ${p.w}px; height: ${h}px; }\n.sf-toggle input { opacity: 0; width: 0; height: 0; }\n.sf-toggle span { position: absolute; inset: 0; background: ${p.off}; border-radius: ${h}px; cursor: pointer; transition: background .25s; }\n.sf-toggle span::before { content: ""; position: absolute; width: ${k}px; height: ${k}px; left: ${p.gap}px; top: ${p.gap}px; background: ${p.knob}; border-radius: 50%; transition: transform .25s cubic-bezier(.4,1.4,.6,1); box-shadow: 0 2px 5px rgba(0,0,0,.3); }\n.sf-toggle input:checked + span { background: ${p.on}; }\n.sf-toggle input:checked + span::before { transform: translateX(${p.w - k - p.gap * 2}px); }${p.anim ? `\n.sf-demo span { animation: sf-bg 3s infinite; } .sf-demo span::before { animation: sf-kn 3s infinite; }\n@keyframes sf-bg { 0%,45% { background: ${p.off}; } 55%,95% { background: ${p.on}; } }\n@keyframes sf-kn { 0%,45% { transform: none; } 55%,95% { transform: translateX(${p.w - k - p.gap * 2}px); } }` : ''}\n/* <label class="sf-toggle"><input type="checkbox"><span></span></label> */`; },
    () => '<label class="sf-toggle sf-demo"><input type="checkbox"><span></span></label>');

  rt('c-slider', 'Range slider', [R('th', 'Track thickness', 2, 16, 6, 'px'), R('knob', 'Knob size', 10, 36, 22, 'px'), C('fill', 'Filled colour', '#7c5cff'), C('track', 'Track colour', '#2a3248'), C('thumb', 'Knob colour', '#ffffff'), R('val', 'Preview value', 0, 100, 60, '%', 1, 1)],
    'Browsers draw range sliders in two engines, so the track and thumb are styled twice. The filled part uses a gradient sized to the value.',
    p => `.sf-slider { -webkit-appearance: none; appearance: none; width: 280px; height: ${p.th}px; border-radius: ${p.th}px; outline: none; background: linear-gradient(90deg, ${p.fill} ${p.val}%, ${p.track} ${p.val}%); }\n.sf-slider::-webkit-slider-thumb { -webkit-appearance: none; width: ${p.knob}px; height: ${p.knob}px; border-radius: 50%; background: ${p.thumb}; box-shadow: 0 2px 8px rgba(0,0,0,.45), 0 0 0 3px ${U.rgba(p.fill, .35)}; cursor: grab; }\n.sf-slider::-moz-range-thumb { width: ${p.knob}px; height: ${p.knob}px; border: 0; border-radius: 50%; background: ${p.thumb}; box-shadow: 0 2px 8px rgba(0,0,0,.45); cursor: grab; }`,
    p => `<input class="sf-slider" type="range" value="${p.val}">`);

  rt('c-input', 'Text field', [S('kind', 'Style', ['Outlined', 'Filled', 'Underline', 'Soft glow'], 'Outlined'), C('line', 'Border colour', '#4a5272'), C('focus', 'Focus colour', '#7c5cff'), R('rad', 'Roundness', 0, 24, 10, 'px'), R('pad', 'Padding', 6, 20, 12, 'px'), B('show', 'Show focused state', 1)],
    'A good field makes focus unmistakable. The focus colour should also be clearly different from the resting border.',
    p => { const k = p.kind, base = k === 'Underline' ? `border: 0; border-bottom: 2px solid ${p.line}; border-radius: 0; background: transparent;` : k === 'Filled' ? `border: 2px solid transparent; background: ${U.rgba(p.line, .25)}; border-radius: ${p.rad}px;` : `border: 2px solid ${p.line}; background: transparent; border-radius: ${p.rad}px;`; const foc = k === 'Underline' ? `border-bottom-color: ${p.focus};` : `border-color: ${p.focus}; ${k === 'Soft glow' ? `box-shadow: 0 0 0 4px ${U.rgba(p.focus, .3)};` : ''}`; return `.sf-input { ${base} color: #fff; padding: ${p.pad}px ${p.pad + 4}px; font: 16px system-ui; outline: none; width: 260px; transition: .2s; }\n.sf-input:focus${p.show ? ', .sf-input.is-focus' : ''} { ${foc} }`; },
    p => `<input class="sf-input${p.show ? ' is-focus' : ''}" placeholder="example: hello@mysite.com">`);

  rt('c-scroll', 'Scrollbar', [R('w', 'Width', 4, 24, 10, 'px'), C('thumb', 'Handle colour', '#7c5cff'), C('hover', 'Handle on hover', '#ff5c9d'), C('track', 'Track colour', '#1c2233'), R('rad', 'Roundness', 0, 12, 8, 'px')],
    'Chrome and Safari style scrollbars with ::-webkit-scrollbar, while Firefox uses scrollbar-color and scrollbar-width. Both are included.',
    p => `.sf-scroll { scrollbar-width: thin; scrollbar-color: ${p.thumb} ${p.track}; }\n.sf-scroll::-webkit-scrollbar { width: ${p.w}px; height: ${p.w}px; }\n.sf-scroll::-webkit-scrollbar-track { background: ${p.track}; border-radius: ${p.rad}px; }\n.sf-scroll::-webkit-scrollbar-thumb { background: ${p.thumb}; border-radius: ${p.rad}px; }\n.sf-scroll::-webkit-scrollbar-thumb:hover { background: ${p.hover}; }`,
    () => `<div class="sf-scroll" style="width:300px;height:210px;overflow:auto;background:#161b2e;border-radius:12px;padding:14px;color:#c9cfe4;font:14px/1.6 system-ui">${'Scroll me. A custom scrollbar should stay visible and easy to grab. '.repeat(14)}</div>`);

  rt('c-check', 'Checkbox & radio', [R('size', 'Size', 14, 36, 22, 'px'), C('on', 'Checked colour', '#7c5cff'), C('line', 'Border colour', '#4a5272'), R('rad', 'Corner roundness (checkbox)', 0, 50, 6, '%'), C('tick', 'Tick colour', '#ffffff', 1)],
    'appearance: none removes the browser style so you can draw your own box; a pseudo-element draws the tick or dot when checked.',
    p => `.sf-check, .sf-radio { -webkit-appearance: none; appearance: none; width: ${p.size}px; height: ${p.size}px; border: 2px solid ${p.line}; background: transparent; display: inline-grid; place-content: center; cursor: pointer; transition: .15s; }\n.sf-check { border-radius: ${p.rad}%; }\n.sf-radio { border-radius: 50%; }\n.sf-check::after { content: ""; width: 40%; height: 70%; border: solid ${p.tick}; border-width: 0 3px 3px 0; transform: rotate(45deg) scale(0); margin-top: -12%; transition: .15s; }\n.sf-radio::after { content: ""; width: 50%; height: 50%; border-radius: 50%; background: ${p.tick}; transform: scale(0); transition: .15s; }\n.sf-check:checked, .sf-radio:checked { background: ${p.on}; border-color: ${p.on}; }\n.sf-check:checked::after { transform: rotate(45deg) scale(1); }\n.sf-radio:checked::after { transform: scale(1); }`,
    () => '<div style="display:flex;gap:22px;align-items:center"><input class="sf-check" type="checkbox" checked><input class="sf-check" type="checkbox"><input class="sf-radio" type="radio" checked><input class="sf-radio" type="radio"></div>');

  rt('c-tooltip', 'Tooltip', [S('pos', 'Position', ['Top', 'Bottom', 'Left', 'Right'], 'Top'), C('bg', 'Background', '#ffffff'), C('text', 'Text colour', '#14182a'), R('arrow', 'Arrow size', 4, 14, 7, 'px'), R('rad', 'Roundness', 0, 20, 8, 'px'), R('pad', 'Padding', 4, 16, 8, 'px', 1, 1)],
    'A tooltip is a small absolutely-positioned box with a triangle made from borders. It is hidden until the parent is hovered.',
    p => { const a = p.arrow, pos = { Top: `bottom: calc(100% + ${a + 2}px); left: 50%; transform: translateX(-50%);`, Bottom: `top: calc(100% + ${a + 2}px); left: 50%; transform: translateX(-50%);`, Left: `right: calc(100% + ${a + 2}px); top: 50%; transform: translateY(-50%);`, Right: `left: calc(100% + ${a + 2}px); top: 50%; transform: translateY(-50%);` }[p.pos], ar = { Top: `top: 100%; left: 50%; margin-left: -${a}px; border-top-color: ${p.bg};`, Bottom: `bottom: 100%; left: 50%; margin-left: -${a}px; border-bottom-color: ${p.bg};`, Left: `left: 100%; top: 50%; margin-top: -${a}px; border-left-color: ${p.bg};`, Right: `right: 100%; top: 50%; margin-top: -${a}px; border-right-color: ${p.bg};` }[p.pos]; return `.sf-tip { position: relative; display: inline-block; }\n.sf-tip .tip { position: absolute; ${pos} background: ${p.bg}; color: ${p.text}; padding: ${p.pad}px ${p.pad * 1.6}px; border-radius: ${p.rad}px; font: 600 13px system-ui; white-space: nowrap; box-shadow: 0 6px 18px rgba(0,0,0,.35); }\n.sf-tip .tip::after { content: ""; position: absolute; border: ${a}px solid transparent; ${ar} }`; },
    () => '<div style="padding:50px"><span class="sf-tip"><button style="padding:10px 18px;border-radius:10px;border:0;background:#2a3248;color:#fff;font:600 14px system-ui">Hover target</button><span class="tip">Helpful hint</span></span></div>');

  rt('c-progress', 'Progress bar', [R('val', 'Progress', 0, 100, 64, '%'), R('h', 'Height', 4, 36, 16, 'px'), C('c1', 'Colour 1', '#7c5cff'), C('c2', 'Colour 2', '#ff5c9d'), C('track', 'Track', '#232a42'), B('stripes', 'Animated stripes', 1), R('rad', 'Roundness', 0, 20, 20, 'px', 1, 1)],
    'A progress bar is a track with a fill whose width is the value. Diagonal stripes on a moving background-position show activity.',
    p => `.sf-progress { width: 320px; height: ${p.h}px; background: ${p.track}; border-radius: ${p.rad}px; overflow: hidden; }\n.sf-progress > i { display: block; height: 100%; width: ${p.val}%; border-radius: ${p.rad}px; background: ${p.stripes ? `repeating-linear-gradient(45deg, rgba(255,255,255,.18) 0 10px, transparent 10px 20px), ` : ''}linear-gradient(90deg, ${p.c1}, ${p.c2});${p.stripes ? ' background-size: 28px 28px, 100% 100%; animation: sf-stripe 1s linear infinite;' : ''} transition: width .4s; }${p.stripes ? '\n@keyframes sf-stripe { to { background-position: 28px 0, 0 0; } }' : ''}`,
    () => '<div class="sf-progress"><i></i></div>');
})();
